mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decideWhatsApp } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-dev2-haiku/work/ours-g5-2/bot.mjs";

const T0 = 1767272400; // webhook timestamp, seconds
const at = (s) => new Date((T0 + s) * 1000);
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: String(T0), ...over });
const ok = { allowed: true, reason: null };

// allowed
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, at(0)), ok);
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, at(86399)), ok);
assert.deepEqual(decideWhatsApp({ type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0)), ok);
assert.deepEqual(decideWhatsApp({ type: "template", contact: c({ lastInboundTimestamp: null }) }, at(10 * 86400)), ok);

// window boundary: exactly 24h closed
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, at(86400)), { allowed: false, reason: "customer_service_window_closed" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, at(86400 * 3)), { allowed: false, reason: "customer_service_window_closed" });

// never written to us
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0)), { allowed: false, reason: "customer_service_window_closed" });

// opt-in
assert.deepEqual(decideWhatsApp({ type: "template", contact: c({ optedIn: false }) }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ optedIn: false }) }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ optedIn: "yes" }) }, at(0)), { allowed: false, reason: "not_opted_in" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ optedIn: undefined }) }, at(0)), { allowed: false, reason: "not_opted_in" });

// timestamp is seconds, not ms: ms interpretation would be far in the past -> must still be open
assert.equal(decideWhatsApp({ type: "text", contact: c() }, new Date(T0 * 1000 + 60000)).allowed, true);

// malformed / future
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(0)), { allowed: false, reason: "invalid_inbound_timestamp" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c({ lastInboundTimestamp: "17672724e2" }) }, at(0)), { allowed: false, reason: "invalid_inbound_timestamp" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, at(-5)), { allowed: false, reason: "invalid_inbound_timestamp" });

// structure
assert.deepEqual(decideWhatsApp({ type: "image", contact: c() }, at(0)), { allowed: false, reason: "invalid_message_type" });
assert.deepEqual(decideWhatsApp({ contact: c() }, at(0)), { allowed: false, reason: "invalid_message_type" });
assert.deepEqual(decideWhatsApp(null, at(0)), { allowed: false, reason: "invalid_message" });
assert.deepEqual(decideWhatsApp({ type: "text" }, at(0)), { allowed: false, reason: "invalid_message" });
assert.deepEqual(decideWhatsApp({ type: "text", contact: c() }, new Date("nope")), { allowed: false, reason: "invalid_clock" });

// reason codes distinct per rule
const codes = ["invalid_message", "invalid_message_type", "not_opted_in", "customer_service_window_closed", "invalid_inbound_timestamp", "invalid_clock"];
assert.equal(new Set(codes).size, codes.length);

console.log("all checks passed");
EOF
